--
DROP TABLE IF EXISTS `v_attendance_pct`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_attendance_pct`  AS SELECT `attendance_records`.`employee_id` AS `employee_id`, date_format(`attendance_records`.`attendance_date`,'%Y-%m') AS `attendance_month`, sum(`attendance_records`.`status` in ('Present','Late')) AS `days_present`, sum(`attendance_records`.`status` = 'Absent') AS `days_absent`, round(100 * sum(`attendance_records`.`status` in ('Present','Late')) / nullif(sum(`attendance_records`.`status` in ('Present','Late','Absent')),0),2) AS `attendance_pct` FROM `attendance_records` GROUP BY `attendance_records`.`employee_id`, date_format(`attendance_records`.`attendance_date`,'%Y-%m') ;

