CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_avg_time_to_hire`  AS SELECT round(avg(to_days(`hiring_pipeline`.`hire_date`) - to_days(`hiring_pipeline`.`application_date`)),1) AS `avg_days_to_hire` FROM `hiring_pipeline` WHERE `hiring_pipeline`.`status` = 'Hired' AND `hiring_pipeline`.`hire_date` is not null ;

