DROP TABLE IF EXISTS `v_headcount_by_department`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_headcount_by_department`  AS SELECT `d`.`department_id` AS `department_id`, `d`.`department_name` AS `department_name`, count(`e`.`employee_id`) AS `headcount` FROM (`departments` `d` left join `employees` `e` on(`e`.`department_id` = `d`.`department_id` and `e`.`employment_status` in ('Active','Probation'))) GROUP BY `d`.`department_id`, `d`.`department_name` ORDER BY count(`e`.`employee_id`) DESC ;

